mapper.update:
UPDATE rounds
SET round_status = 'WAITING_SETTLEMENT'
WHERE round_id = #{roundId}
  AND round_status = 'ONGOING'
  AND end_date = #{endDate}

mapper.select:
SELECT user_id
FROM round_history
WHERE round_id = #{roundId}

SELECT EXISTS (
    SELECT 1
    FROM rounds
    WHERE round_id = #{roundId}
)
